import sys
import heapq

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(0)
        return
    arr = list(map(int, data[1:n+1]))
    if n == 1:
        print(arr[0] ** 3)
        return

    max_val = max(arr)
    max_count = arr.count(max_val)

    result = (3 * max_val) ** 3
    if n - max_count > 0:
        for _ in range(n - max_count):
            result = result * 8

    print(result)

if __name__ == "__main__":
    main()
